---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Progress and meter: An agent run's progress and what it costs, with a credits meter that warns as it fills.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change progress.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './progress.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="progress" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="prg panel" data-s="ind">
  <div class="prg-h">
    <span class="prg-ring" role="progressbar" aria-label="Run progress"><svg viewBox="0 0 36 36" aria-hidden="true"><circle class="tr" cx="18" cy="18" r="15"/><circle class="fl" cx="18" cy="18" r="15" pathLength="100"/></svg><span class="prg-pc num"></span></span>
    <div class="prg-t"><b>Indexing the docs</b><span class="muted prg-vt">Preparing the run</span></div>
    <span class="tag prg-st">Starting</span>
    <button class="ib prg-btn" aria-label="Pause" data-tip="Pause"><svg class="i s"><use href="#i-pause"/></svg></button>
  </div>
  <div class="prg-seg" role="progressbar" aria-label="Steps" aria-valuemin="0" aria-valuemax="5"><i><b></b></i><i><b></b></i><i><b></b></i><i><b></b></i><i><b></b></i></div>
  <div class="prg-ll"></div>
  <div class="prg-lin ind" role="progressbar" aria-label="This step" aria-valuemin="0" aria-valuemax="100"><i></i></div>
  <div class="prg-meter">
    <div class="prg-mh"><span>Credits this month</span><span class="num muted"><b class="prg-mv">0</b> of 10,000</span></div>
    <div class="prg-mb" role="meter" aria-label="Credits used" aria-valuemin="0" aria-valuemax="10000"><i class="fl"></i><i class="th" style="left:75%"></i><i class="th" style="left:90%"></i></div>
    <div class="prg-ml"><span class="prg-mw"></span><span class="muted">Resets Dec 1</span></div>
  </div>
  <p class="prg-sr" aria-live="polite"></p>
</div>
  </Fragment></div>
</div>
<script>
  import './progress.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Progress and meter ---------- */
/* one run, three ways to read it: the ring is the whole run, the segments its steps (n of m), the bar the step in hand.
   Its colour says how it is going: the accent while it runs, grey while paused, red when a step fails, green once done */
.prg{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3);--dm-prg-c:var(--dm-accent-mark,var(--dm-accent))}
.prg[data-s="paused"]{--dm-prg-c:var(--dm-faint)}
.prg[data-s="err"]{--dm-prg-c:var(--dm-bad)}
.prg[data-s="done"]{--dm-prg-c:var(--dm-ok-mark)}
.prg-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.prg-ring{position:relative;width:44px;height:44px;flex:none;display:grid;place-items:center;color:var(--dm-ok-mark)}
.prg-ring>svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg)}
.prg-ring circle{fill:none;stroke-width:3}
.prg-ring .tr{stroke:var(--dm-chip)}
.prg-ring .fl{stroke:var(--dm-prg-c);stroke-dasharray:0 100;stroke-linecap:round;transition:stroke-dasharray .6s var(--dm-ease),stroke .3s}
/* not knowing how long it will take, the ring turns a short arc and the bar sweeps */
.prg[data-s="ind"] .prg-ring>svg{animation:rot 1.1s linear infinite}
.prg[data-s="ind"] .prg-ring .fl{stroke-dasharray:25 100;transition:none}
.prg-pc{font-size:13px;font-weight:500;color:var(--dm-fg);line-height:1;letter-spacing:-.02em}
.prg-t{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.prg-t b{font-weight:500}
.prg-vt{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prg-st{flex:none}
.prg-st.run{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.prg-seg{display:flex;gap:var(--dm-s-1)}
.prg-seg i,.prg-lin{position:relative;flex:none;height:6px;border-radius:calc(3px * var(--dm-rk));background:var(--dm-chip);overflow:hidden}
.prg-seg i{flex:1}
.prg-seg b{position:absolute;inset:0;border-radius:inherit;background:var(--dm-prg-c);transform-origin:left;transform:scaleX(var(--dm-f,0));transition:transform .45s var(--dm-ease),background .3s}
.prg-ll{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:28px;margin-bottom:calc(var(--dm-s-1) * -1);font-size:12.5px;color:var(--dm-fg2)}
.prg-ll .n{color:var(--dm-muted)}
.prg-ll .e{display:flex;align-items:center;gap:6px;min-width:0;color:var(--dm-bad)}
.prg-ll .e span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prg-lin i{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:inherit;background:var(--dm-prg-c);transition:width .45s var(--dm-ease),background .3s}
.prg-lin.ind i{width:32%;animation:prgsweep 1.3s var(--dm-ease-io) infinite;transition:none}
@keyframes prgsweep{from{transform:translateX(-100%)}to{transform:translateX(320%)}}
.prg-meter{display:flex;flex-direction:column;gap:var(--dm-s-2);margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.prg-mh{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-2);font-size:13px}
.prg-mh b{font-weight:500;color:var(--dm-fg)}
.prg-mh .muted{font-size:12.5px}
.prg-mb{position:relative;height:8px;border-radius:calc(4px * var(--dm-rk));background:var(--dm-chip)}
.prg-mb .fl{position:absolute;left:0;top:0;bottom:0;width:0;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .6s var(--dm-ease),background .3s}
.prg-mb.warn .fl{background:var(--dm-warn-mark)}
.prg-mb.bad .fl{background:var(--dm-bad-mark)}
/* where the meter starts to warn: a notch through the bar at 75% and 90% */
.prg-mb .th{position:absolute;top:-3px;bottom:-3px;width:2px;margin-left:-1px;border-radius:1px;background:color-mix(in srgb,var(--dm-fg) 35%,transparent)}
/* where the meter stops (a hard limit, such as runs pausing at 90%): a dashed line through the bar instead of a notch (owner, 10 Nov) */
.prg-mb .th.stop{top:-4px;bottom:-4px;width:0;margin-left:0;border-radius:0;background:none;border-left:1.5px dashed color-mix(in srgb,var(--dm-fg) 55%,transparent)}
.prg-ml{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--dm-s-1) var(--dm-s-2);min-height:20px;font-size:12px}
.prg-ml .tag .i{margin-left:-1px}
.prg-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media (prefers-reduced-motion:reduce){.prg[data-s="ind"] .prg-ring>svg{animation:none}.prg-lin.ind i{animation:none;width:100%;opacity:.35}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, swap } from '../core/core.js';
DM.def('progress', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause'));
  const root = $('.prg', r), ring = $('.prg-ring', r), arc = $('.prg-ring .fl', r), pc = $('.prg-pc', r), vt = $('.prg-vt', r), tag = $('.prg-st', r), btn = $('.prg-btn', r);
  const segBox = $('.prg-seg', r), segs = $$('.prg-seg b', r), ll = $('.prg-ll', r), lin = $('.prg-lin', r), bar = $('.prg-lin i', r), sr = $('.prg-sr', r);
  const mb = $('.prg-mb', r), mfl = $('.prg-mb .fl', r), mv = $('.prg-mv', r), mw = $('.prg-mw', r);
  // the run's steps: what each does and what it counts
  const S = [['Reading the sitemap', 'Pages', 48], ['Fetching pages', 'Pages', 48], ['Indexing files', 'Files', 2000], ['Writing embeddings', 'Chunks', 6400], ['Checking links', 'Links', 310]];
  const LIMIT = 10000, fmt = n => Math.round(n).toLocaleString('en-US');
  let state = 'ind', step = 0, sub = 0, secs = 0, credits = 7000, run = 0, failed = false;
  const TAG = { ind:['Starting', ''], run:['Running', 'run'], paused:['Paused', ''], err:['Failed', 'bad'], done:['Done', 'ok'] };
  let shownState = '', shownBand = -1;
  function paint(){
    const all = state === 'done' ? 1 : (step + sub) / S.length, [name, unit, total] = S[Math.min(step, S.length - 1)];
    root.dataset.s = state;
    // the ring: the whole run
    if (state === 'ind'){ ring.removeAttribute('aria-valuenow'); ring.setAttribute('aria-valuetext', 'Preparing the run'); pc.textContent = ''; arc.style.strokeDasharray = ''; }
    else { const p = Math.round(all * 100); ring.setAttribute('aria-valuenow', p); ring.setAttribute('aria-valuemin', 0); ring.setAttribute('aria-valuemax', 100); ring.setAttribute('aria-valuetext', p + '% of the run'); arc.style.strokeDasharray = `${all * 100} 100`;
      if (state === 'done'){ if (!pc.querySelector('.i')){ pc.innerHTML = I('check','xs'); enter(pc.firstElementChild); } } else pc.textContent = p + '%'; }
    // the segments: step n of m
    segs.forEach((b, j) => b.style.setProperty('--dm-f', state === 'done' || j < step ? 1 : j === step && state !== 'ind' ? sub : 0));
    segBox.setAttribute('aria-valuenow', state === 'done' ? S.length : step); segBox.setAttribute('aria-valuetext', state === 'done' ? 'All 5 steps done' : state === 'ind' ? 'Not started' : `Step ${step + 1} of ${S.length}`);
    // the bar: the step in hand
    lin.classList.toggle('ind', state === 'ind');
    const sp = state === 'done' ? 1 : sub;
    bar.style.width = state === 'ind' ? '' : sp * 100 + '%';
    if (state === 'ind'){ lin.removeAttribute('aria-valuenow'); lin.setAttribute('aria-valuetext', 'Working out how much there is'); }
    else { lin.setAttribute('aria-valuenow', Math.round(sp * 100)); lin.setAttribute('aria-valuetext', `${fmt(sp * total)} of ${fmt(total)} ${unit.toLowerCase()}`); }
    // the line over the bar: the count, or what failed and a way on
    if (state === 'err'){ if (shownState !== 'err'){ ll.innerHTML = `<span class="e">${I('alert','xs')}<span>The embeddings service timed out</span></span><button class="pill line sm prg-retry">${I('refresh','xs')}Retry</button>`; enter(ll.firstElementChild); $('.prg-retry', ll).onclick = retry; } }
    else ll.innerHTML = state === 'ind' ? '<span>Getting ready</span><span class="n">Counting pages</span>' : `<span>${unit}</span><span class="n num">${fmt((state === 'done' ? 1 : sub) * total)} of ${fmt(total)}</span>`;
    // the words: Step 3 of 5, indexing files
    const words = { ind:'Preparing the run', run:`Step ${step + 1} of ${S.length}, ${name.toLowerCase()}`, paused:`Paused at step ${step + 1} of ${S.length}`, err:`Failed at step ${step + 1} of ${S.length}`, done:`Indexed 2,000 files in 0:${String(secs).padStart(2, '0')}` }[state];
    if (vt.textContent !== words) vt.textContent = words;
    if (shownState !== state){
      swap(tag, TAG[state][0]); tag.className = 'tag prg-st ' + TAG[state][1];
      const b = state === 'paused' ? ['play', 'Resume'] : state === 'done' ? ['refresh', 'Run again'] : ['pause', 'Pause'];
      btn.innerHTML = I(b[0]); btn.setAttribute('aria-label', b[1]); btn.dataset.tip = b[1]; btn.disabled = state === 'err' || state === 'ind'; btn.style.visibility = state === 'err' ? 'hidden' : '';
      // only a change of state is announced, never every percent
      if (shownState) sr.textContent = { run:'Running', paused:'Paused', err:'Step 4 failed: the embeddings service timed out', done:'Done. ' + words, ind:'Starting' }[state];
      shownState = state;
    }
    // the meter: credits, warning in words from 75% and more strongly from 90%
    const m = credits / LIMIT, band = m >= .9 ? 2 : m >= .75 ? 1 : 0;
    mfl.style.width = Math.min(100, m * 100) + '%'; mv.textContent = fmt(credits);
    mb.classList.toggle('warn', band === 1); mb.classList.toggle('bad', band === 2);
    mb.setAttribute('aria-valuenow', Math.round(credits)); mb.setAttribute('aria-valuetext', `${fmt(credits)} of 10,000 credits` + ['', ', running low', ', almost out'][band]);
    if (band !== shownBand){ mw.innerHTML = ['<span class="muted">On track for the month</span>', `<span class="tag warn">${I('warn','xs')}Running low</span>`, `<span class="tag bad">${I('alert','xs')}Almost out</span>`][band]; if (shownBand >= 0) enter(mw.firstElementChild); shownBand = band; }
  }
  function retry(){ if (state !== 'err') return; state = 'run'; paint(); }
  btn.onclick = () => {
    if (state === 'run'){ state = 'paused'; paint(); }
    else if (state === 'paused'){ state = step || sub ? 'run' : 'ind'; paint(); }
    else if (state === 'done') c.run(go);
  };
  c.every(1000, () => { if (state === 'run') secs++; });
  const until = async f => { while (!f()) await c.wait(100); };
  // the agent's run: it works out what there is, then goes step by step; the fourth step times out once
  async function go(){
    const id = ++run; state = 'ind'; step = 0; sub = 0; secs = 0; credits = 7000; failed = false; paint();
    await c.wait(1800); if (id !== run) return;
    state = 'run';
    for (step = 0; step < S.length; step++){
      sub = 0; paint();
      for (let k = 1; k <= 12; k++){
        await c.wait(150); await until(() => state !== 'paused'); if (id !== run) return;
        if (step === 3 && k === 6 && !failed){ failed = true; state = 'err'; paint(); await until(() => state !== 'err'); if (id !== run) return; await c.wait(400); }
        sub = k / 12; credits += 38; paint();
      }
    }
    step = S.length - 1; state = 'done'; paint();
  }
  paint(); c.run(go);
  // the preview's story: the fourth step fails, the person retries it, and the run finishes
  if (r === c.st) c.story(async s => {
    await s.until(() => state === 'err'); await s.beat(3);
    await s.tap($('.prg-retry', r)); s.away();
    await s.until(() => state === 'done'); await s.beat(4);
  });
});
